'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils/constant-function' );
var SQRT2 = require( '@stdlib/constants/float64/sqrt-two' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var exp = require( '@stdlib/math/base/special/exp' );
var erfc = require( '@stdlib/math/base/special/erfc' );


// MAIN //

/**
* Evaluates the moment-generating function (MGF) for a half-normal distribution with scale parameter `sigma` at a value `t`.
*
* @param {PositiveNumber} sigma - scale parameter
* @returns {Function} MGF
*
* @example
* var mgf = factory( 1.0 );
*
* var y = mgf( 1.0 );
* // returns ~2.774
*
* y = mgf( 0.5 );
* // returns ~1.567
*/
function factory( sigma ) {
	var A;
	var B;
	if (
		isnan( sigma ) ||
		sigma <= 0.0
	) {
		return constantFunction( NaN );
	}
	A = -sigma / SQRT2;
	B = 0.5 * sigma * sigma;
	return mgf;

	/**
	* Evaluates the moment-generating function (MGF) for a half-normal distribution with scale parameter `sigma` at a value `t`.
	*
	* @private
	* @param {number} t - input value
	* @returns {number} evaluated MGF
	*/
	function mgf( t ) {
		var V;
		var W;
		if ( isnan( t ) ) {
			return NaN;
		}
		V = A * t;
		W = t * t;
		return exp( B * W ) * erfc( V );
	}
}


// EXPORTS //

module.exports = factory;
